// or non-numeric pid is Unprotected: it names no process, so there is nothing
// to protect. It runs on every render, hence the lazy creation-time read.
func ProtectionOf(pid string) Protection {
	n, err := strconv.Atoi(pid)
	if err != nil {
		return Unprotected
	}
	return protectionOf(n)
}

